mapper.select:
SELECT c.id, c.user_id, u.nick_name, u.icon, c.rating, c.content, UNIX_TIMESTAMP(c.create_time) * 1000 AS created_at FROM tb_shop_comment c INNER JOIN tb_user u ON u.id = c.user_id WHERE c.shop_id = #{shopId} AND c.status = 0
AND c.rating = #{rating}
ORDER BY c.create_time DESC, c.id DESC LIMIT #{offset}, #{limit}
